    33  fr_dns_labels_t *fr_dns_labels_init(TALLOC_CTX *ctx, uint8_t const *packet, int max_labels)
    34  {
    35          fr_dns_labels_t *lb;
    36
    37          lb = (fr_dns_labels_t *) talloc_zero_array(ctx, uint8_t, sizeof(fr_dns_labels_t) + sizeof(lb->blocks[0]) * max_labels);
    38          if (!lb) return NULL;
    39
    40          talloc_set_name_const(lb, "fr_dns_labels_t");
    41
    42          lb->start = packet;
    43          lb->max = max_labels;
    44
    45          /*
    46           *      Always skip the DNS packet header.
    47           */
    48          lb->blocks[0].start = 12;
    49          lb->blocks[0].end = 12;
    50          lb->num = 1;
    51
    52          return lb;
    53  }
